import * as yup from 'yup';

const aminoAcidSchema = yup
  .string()
  .matches(/^[ARNDCEQGHILKMFPSTWYV-]+$/, {
    excludeEmptyString: true,
    message: 'Некорректная аминокислотная последовательность',
  })
  .required('Обязательное поле');

export const formSchema = yup
  .object()
  .shape({
    acid1: aminoAcidSchema,
    acid2: aminoAcidSchema,
  })
  .test('is-same-length', 'Длина последовательностей должна совпадать', function ({ acid1, acid2 }) {
    if (acid1.length === acid2.length) {
      return true;
    }
    return this.createError({ path: 'acid2', message: 'Длина последовательностей должна совпадать' });
  });
