import { Box } from '@mui/material';
import { useMemo } from 'react';
import { colorMap } from './colorMap';

type AminoAcidSequenceProps = {
    sequence: string;
    sequenceToCompare?: string;
    marginTop?: string;
};

export const AminoAcidSequence = ({ sequence, sequenceToCompare, marginTop = '0rem' }: AminoAcidSequenceProps) => {
    const line = useMemo(() =>
        sequence.split('').map((letter, i) => {
            const letterToCompare = sequenceToCompare?.[i];
            const color = letter === letterToCompare ? 'white' : colorMap[letter];

            return (
                <span
                    key={`${i}-${letter}`}
                    style={{
                        fontFamily: 'monospace',
                        backgroundColor: color,
                        userSelect: 'text',
                        fontSize: 16,
                        letterSpacing: '0.2rem',
                        height: '1.5rem',
                        alignContent: 'center',
                    }}
                >
                    {letter}
                </span>
            );
        }),
        [sequence, sequenceToCompare]
    );

    return (
        <Box
            position='absolute'
            width='100%'
        >
            <Box
                display='flex'
                flexDirection='row'
                flexWrap='wrap'
                position='absolute'
                zIndex={-1}
                rowGap='4.5rem'
                marginTop={`calc(2.3rem + ${marginTop})`}
                id={sequenceToCompare ? 'sequence-to-compare' : 'sequence'}
            >
                {line}
            </Box>
            <Box
                position='absolute'
                fontFamily='monospace'
                fontSize={16}
                sx={{
                    wordBreak: 'break-all',
                    userSelect: 'none',
                    pointerEvents: 'none',
                }}
                letterSpacing='0.2rem'
                lineHeight='6rem'
                marginTop={marginTop}
                color='transparent'

            >
                {sequence}
            </Box>

        </Box>
    );
};
