import { ComparisonFormFields } from '@/entities/comparisonFormFields';
import { Notification } from '@/shared/notification/Notification';
import { AminoAcidSequence } from '@/widgets/AminoAcidSequences/AminoAcidSequence';
import { SequenceComparisonForm } from '@/widgets/SequenceComparisonForm';
import { Box, Container } from '@mui/material';
import { useEffect, useState } from 'react';

export const SequenceComparison = () => {
    const [copiedSequence, setCopiedSequence] = useState<string>('');
    const [state, setState] = useState<ComparisonFormFields>();

    const handleFormSubmit = (data: ComparisonFormFields) => {
        setState(data);
    };

    const handleClose = () => {
        setCopiedSequence('');
    };

    useEffect(() => {
        const onMouseUp = () => {
            const selection = window.getSelection();
            if (!selection || selection.toString().length === 0 || !state?.acid1 || !state.acid2) return;

            const copied = selection.toString().replace(/\n/g, '');

            if (
                state.acid1.indexOf(copied) ||
                state.acid2.indexOf(copied)) {

                navigator.clipboard.writeText(copied);
                setCopiedSequence(copied);
            }
        };

        document.addEventListener('mouseup', onMouseUp);
        return () => document.removeEventListener('mouseup', onMouseUp);
    }, [state?.acid1, state?.acid2]);


    return (
        <Container sx={{ paddingTop: '20vh' }}>
            <Box
                width={{ xs: '80vw', sm: '40vw', lg: '25vw' }}
                sx={{ marginX: 'auto' }}
            >
                <SequenceComparisonForm onSubmit={handleFormSubmit} />
            </Box>
            {state?.acid1 && state.acid2 && (
                <Box
                    marginTop='5vh'
                    position='relative'
                >
                    <AminoAcidSequence sequence={state.acid1} />
                    <AminoAcidSequence
                        sequence={state.acid2}
                        sequenceToCompare={state.acid1}
                        marginTop='2rem'
                    />
                </Box>
            )}
            <Notification
                opened={copiedSequence.length > 0}
                onClose={handleClose}
                message='Последовательность скопирована!'
            />
        </Container>
    );
};
