import { ComparisonFormFields } from '@/entities/comparisonFormFields';
import { yupResolver } from '@hookform/resolvers/yup';
import { Button, Stack, TextField } from '@mui/material';
import { Controller, useForm } from 'react-hook-form';
import { formSchema } from './formSchema';

type SequenceComparisonFormProps = {
    onSubmit: (data: ComparisonFormFields) => void;
};

export const SequenceComparisonForm = ({ onSubmit }: SequenceComparisonFormProps) => {
    const {
        control,
        handleSubmit,
        formState: { errors },
        reset,
    } = useForm({
        mode: 'onChange',
        resolver: yupResolver(formSchema),
        reValidateMode: 'onChange',
        defaultValues: {
            acid1: '',
            acid2: '',
        },
    });

    const handleFormSubmit = (data: ComparisonFormFields) => {
        onSubmit({...data});
        reset({ acid1: '', acid2: '' });
    }

    return (
        <form onSubmit={handleSubmit(handleFormSubmit)}>
            <Stack
                spacing={1}
                justifyContent='center'
            >
                <Controller
                    name='acid1'
                    control={control}
                    render={({ field: { ref, ...field } }) => (
                        <TextField
                            inputRef={ref}
                            {...field}
                            variant='outlined'
                            size='small'
                            placeholder='VLSPADKTNIKASWEKIGSHG'
                            error={!!errors.acid1?.message}
                            helperText={errors.acid1?.message || ' '}
                        />
                    )}
                />
                <Controller
                    name='acid2'
                    control={control}
                    render={({ field: { ref, ...field } }) => (
                        <TextField
                            inputRef={ref}
                            {...field}
                            variant='outlined'
                            size='small'
                            placeholder='VLSPADKTNIKASWEKIGSHG'
                            error={!!errors.acid2?.message}
                            helperText={errors.acid2?.message || ' '}
                        />
                    )}
                />
                <Button
                    variant='contained'
                    type='submit'
                >
                    Выровнять
                </Button>
            </Stack>
        </form>
    );
};
